import React, { forwardRef, useRef } from 'react';

import { PieChartLegend } from './legend/PieChartLegend.js';
import { PieChartOverlays } from './PieChartOverlays/PieChartOverlays.js';
import { PieChartPlot } from './PieChartPlot/PieChartPlot.js';
import { useMergeRefs } from '../../../core/hooks/useMergeRefs.js';
import { ChartLayout } from '../../core/components/chart-layout/ChartLayout.js';
import { OverrideRatioFunction } from '../../core/components/chart-layout/types.js';
import { sanitizeLegendRatio } from '../../core/functions/sanitize-legend-ratio.js';
import { useChartLegend } from '../context/ChartLegendContext.js';
import { usePieHandlers } from '../hooks/usePieHandlers.js';
import { usePieState } from '../hooks/usePieState.js';
import {
  DEFAULT_SIZE,
  PIE_CATEGORICAL_LEGEND_SIZES,
} from '../types/default.js';
import { InternalSliceData } from '../types/internal/pie-chart.js';
import { PieChartProps } from '../types/pie-chart.config.js';

type PieChartInternalProps = Omit<PieChartProps, 'data'> & {
  variant: 'donut' | 'pie';
  data: InternalSliceData[];
  height?: string | number;
  width?: number;
  isEmpty?: boolean;
  emptyState?: React.ReactNode;
  errorState?: React.ReactNode | ((message: string) => JSX.Element);
};

export const PieChartInternal = forwardRef<
  HTMLDivElement,
  PieChartInternalProps
>((props, forwardedRef) => {
  const {
    height,
    width,
    data,
    isEmpty,
    emptyState,
    errorState,
    loading = false,
    className,
    style,
  } = props;
  const { updateSlices, slicesMap, slices } = usePieState(data);
  const { hidden, resizable, position, ratio = 25 } = useChartLegend();
  const sanitizedRatio = sanitizeLegendRatio(ratio);
  const plotAreaRef = useRef<HTMLDivElement>(null);
  const mergedRef = useMergeRefs([forwardedRef, plotAreaRef]);

  const { onLegendItemHover, onLegendItemClicked } = usePieHandlers(
    updateSlices,
    slicesMap,
  );

  const overrideRatio: OverrideRatioFunction = (orientation, width, height) => {
    const isHorizontal = orientation === 'horizontal';
    const legendHeight = isHorizontal ? height : sanitizedRatio * height * 0.01;
    const legendWidth = isHorizontal ? width - height : width;

    return {
      width: legendWidth,
      height: legendHeight,
    };
  };
  const legendConfig = {
    orientation: hidden ? undefined : position,
    overrideRatio,
    ratio: !resizable && position === 'bottom' ? sanitizedRatio : undefined,
    hidden,
    sizes: PIE_CATEGORICAL_LEGEND_SIZES,
  };

  return (
    <ChartLayout
      chartWidth={width ?? '100%'}
      chartHeight={height ?? DEFAULT_SIZE}
      resizable={resizable}
      isEmpty={isEmpty}
      emptyState={emptyState}
      errorState={errorState}
      squaredPlotArea
      showLoader={loading}
      legendConfig={legendConfig}
      className={className}
      style={style}
    >
      <ChartLayout.Graph>
        <PieChartOverlays slices={slices}>
          <PieChartPlot {...props} ref={mergedRef} data={slices} />
        </PieChartOverlays>
      </ChartLayout.Graph>
      <ChartLayout.Legend>
        {!hidden && (
          <PieChartLegend
            data={data}
            onHover={onLegendItemHover}
            onClick={onLegendItemClicked}
          />
        )}
      </ChartLayout.Legend>
    </ChartLayout>
  );
});

PieChartInternal['displayName'] = 'PieChartInternal';
